def load() -> pd.DataFrame:
    import pandas as pd
    return pd.read_csv('data/environment/input/monthly_precipitations_chatham.csv')

def process(rain):
    import pandas as pd
    # keep only rows where Year is a year number (drop summary rows like Min/Max)
    df = rain.copy()
    # Year came in as datetime; extract year
    df['year'] = pd.to_datetime(df['Year'], errors='coerce').dt.year
    df = df[df['year'].between(1900, 2100)]

    months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

    def to_num(x):
        if pd.isna(x):
            return pd.NA
        s = str(x).strip()
        if s.upper() == 'M' or s == '':
            return pd.NA
        # some cells include trailing year like '1.56 2020'
        s = s.split()[0]
        try:
            return float(s)
        except Exception:
            return pd.NA

    for m in months:
        df[m] = df[m].map(to_num).astype('float')

    # impute missing per month using median across non-missing years
    for m in months:
        med = df[m].median(skipna=True)
        df[m] = df[m].fillna(med)

    # compute summer rainfall
    df['summer_rain'] = df[['Jun','Jul','Aug']].sum(axis=1)
    return df[['year'] + months + ['summer_rain']].sort_values('year').reset_index(drop=True)

def process(rain):
    import pandas as pd
    import numpy as np

    df = rain.copy()
    # Year came in as datetime; extract numeric year and keep plausible year rows
    df['year'] = pd.to_datetime(df['Year'], errors='coerce').dt.year
    df = df[df['year'].between(1900, 2100)].copy()

    months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

    def to_num(x):
        if pd.isna(x):
            return np.nan
        s = str(x).strip()
        if s.upper() == 'M' or s == '':
            return np.nan
        # some cells include trailing year like '1.56 2020'
        s = s.split()[0]
        try:
            return float(s)
        except Exception:
            return np.nan

    for m in months:
        df[m] = df[m].map(to_num).astype(float)

    # impute missing per month using median across non-missing years
    for m in months:
        med = df[m].median(skipna=True)
        df[m] = df[m].fillna(med)

    df['summer_rain'] = df[['Jun','Jul','Aug']].sum(axis=1)

    return (
        df[['year'] + months + ['summer_rain']]
        .sort_values('year')
        .reset_index(drop=True)
    )

